yaml:
apiVersion: ladder.dev/v1alpha1
kind: WorkflowBundle
metadata:
  name: commercial-credit-underwriting
  title: Commercial credit underwriting bundle
  description: Borrower intake, KYC, collateral, credit analysis, covenant evidence, approval, and a financial-services ontology sliver.
  version: 1.0.0
spec:
  workflowRef: ladder://workflows/builtin/wf-fin-04
  ontology:
    ref: ladder://ontologies/builtin/financial-services
    mode: sliver
    selection:
      propertyRefs:
        - customer_party.applicant_legal_name
        - loan_facility.requested_loan_amount
        - loan_facility.loan_purpose
        - loan_facility.risk_rating
        - loan_facility.proposed_commitment_amount
        - collateral.market_value
      relationshipIds: [obligated_under, secured_by]
  forms:
    - { ref: ladder://forms/docubricks/fs/commercial_loan_application, role: start }
    - { ref: ladder://forms/docubricks/fs/kyc_cdd_form, role: review }
    - { ref: ladder://forms/docubricks/fs/covenant_compliance_certificate, role: review }
  documents:
    - { ref: ladder://documents/docubricks/fs/collateral_schedule, role: supporting }
    - { ref: ladder://documents/docubricks/fs/commercial_credit_memo, role: supporting }
    - { ref: ladder://documents/docubricks/fs/loan_agreement, role: supporting }
    - { ref: ladder://documents/docubricks/fs/security_agreement, role: supporting }
  bindings:
    - id: applicant-to-intake
      source: { ref: ladder://forms/docubricks/fs/commercial_loan_application, path: /spec/pages/0/sections/3/fields/0 }
      target: { ref: ladder://workflows/builtin/wf-fin-04, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/applicant }
      ontologyPropertyRef: customer_party.applicant_legal_name
      direction: input
    - id: amount-to-intake
      source: { ref: ladder://forms/docubricks/fs/commercial_loan_application, path: /spec/pages/0/sections/2/fields/1 }
      target: { ref: ladder://workflows/builtin/wf-fin-04, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/requested_amount }
      ontologyPropertyRef: loan_facility.requested_loan_amount
      direction: input
    - id: purpose-to-intake
      source: { ref: ladder://forms/docubricks/fs/commercial_loan_application, path: /spec/pages/0/sections/2/fields/2 }
      target: { ref: ladder://workflows/builtin/wf-fin-04, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/loan_purpose }
      ontologyPropertyRef: loan_facility.loan_purpose
      direction: input
    - id: kyc-rating-to-review
      source: { ref: ladder://forms/docubricks/fs/kyc_cdd_form, path: /spec/pages/0/sections/5/fields/0 }
      target: { ref: ladder://workflows/builtin/wf-fin-04, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/kyc_profile }
      ontologyPropertyRef: loan_facility.risk_rating
      direction: review
    - id: collateral-to-intake
      source: { ref: ladder://documents/docubricks/fs/collateral_schedule, path: /spec/fields/7 }
      target: { ref: ladder://workflows/builtin/wf-fin-04, path: /spec/nodes/0/inputSchema/properties/workflowFields/properties/collateral }
      ontologyPropertyRef: collateral.market_value
      direction: input
    - id: commitment-to-credit-review
      source: { ref: ladder://documents/docubricks/fs/commercial_credit_memo, path: /spec/fields/6 }
      target: { ref: ladder://workflows/builtin/wf-fin-04, path: /spec/nodes/2/prompt }
      ontologyPropertyRef: loan_facility.proposed_commitment_amount
      direction: review
